-- SET A（100件 ID 101〜200）：担当未登録 + 点検期限超過 + 要修理
--   グループ1（25件）: 正常→正常→要観察→要修理
--   グループ2（25件）: 正常→要観察→要修理→正常(修理後)→要修理(再発)
--   グループ3（25件）: 正常→正常→要観察→要修理→要修理(長引く)
--   グループ4（25件）: 要観察→要修理→正常(修理後)→要修理(再発)
-- SET B（100件 ID 201〜300）：点検期限間近（正常点検履歴あり）
